fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // All three vectors must have the same length.
    let len = condition.len();
    assert_eq!(x.len(), len, "x and condition must have the same length");
    assert_eq!(y.len(), len, "y and condition must have the same length");

    // Zip the three vectors together and select element-wise.
    condition
        .into_iter()
        .zip(x.into_iter())
        .zip(y.into_iter())
        .map(|((cond, xv), yv)| if cond { xv } else { yv })
        .collect()
}

